import {CREW,JOBS,rank,difficulty,pumpFactor,leakFactor,abilityCost,upgradeCost,newProfile,reward,buy,validProfile} from './rpg-model.mjs';
import {W,LEVELS,fresh,groups,matchScore,refill,waterHeight,releasedCrabs,specialClear} from './engine.mjs';
import {pieceNames,pieceSVG} from './pieces.mjs';
const $=id=>document.getElementById(id), KEY='low-tide-guild-v1';
let p=newProfile(),paused=true,busy=false,selected=null,lastTick=performance.now(),saveClock=0;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(validProfile(saved))p=saved;else{const old=JSON.parse(localStorage.getItem('pocket-bilge-voyage-v3-voyage'));if(CREW[old?.character])p.character=old.character;}}catch{}
function save(){if(busy)return;try{localStorage.setItem(KEY,JSON.stringify(p));}catch{$('saved-note').textContent='Saving is unavailable in this browser. Keep this tab open to retain progress.';}}
function harbor(){const c=CREW[p.character];$('profile-name').textContent=c.name;$('profile-rank').textContent=`Rank ${rank(p)} · ${c.role}`;$('profile-portrait').style.backgroundPosition=c.position;$('coins').textContent=p.coins;$('xp').value=p.xp%300;$('xp-text').textContent=`${p.xp%300} / 300 XP to rank ${rank(p)+1}`;$('completed').textContent=`${p.completed} jobs completed`;
$('crew').innerHTML=Object.entries(CREW).map(([id,c])=>`<button class="crew-card" data-crew="${id}" aria-pressed="${id===p.character}" ${p.active?'disabled':''}><span class="portrait" style="background-position:${c.position}"></span><strong>${c.name}</strong><small>${c.perk}</small></button>`).join('');
$('difficulty-note').textContent='Difficulty grows with rank';$('jobs').innerHTML=JOBS.map(j=>`<article class="job"><div><h3>${j.name}</h3><p>${j.desc}</p><small>${j.target} work · ${j.coins} coins · ${j.xp} XP<br>${LEVELS[difficulty(p,j)].colors} patterns · ${LEVELS[difficulty(p,j)].name}</small></div><button data-job="${j.id}" ${p.active||rank(p)<j.rank?'disabled':''}>${rank(p)<j.rank?`Rank ${j.rank}`:'Take job'}</button></article>`).join('');
$('upgrades').innerHTML=['pump','seal'].map(k=>`<article class="upgrade"><div><h3>${k==='pump'?'Pump strength':'Hull seals'} · ${p.upgrades[k]}/3</h3><p>${k==='pump'?'+10% water removal per level':'10% less incoming water per level'}</p></div><button data-upgrade="${k}" ${p.active||p.upgrades[k]>=3||p.coins<upgradeCost(p,k)?'disabled':''}>${p.upgrades[k]>=3?'Max level':`${upgradeCost(p,k)} coins`}</button></article>`).join('');
$('resume-card').hidden=!p.active;if(p.active)$('resume-copy').textContent=`${JOBS.find(j=>j.id===p.active.job).name} · ${Math.floor(p.active.work)} work · water ${Math.round(p.active.water)}%. Paused until you return.`;
}
const say=s=>$('feedback').textContent=s;
function meters(){const a=p.active;if(!a)return;const j=JOBS.find(j=>j.id===a.job);$('work-label').textContent=`Work ${Math.floor(a.work)} / ${j.target}`;$('work-meter').value=Math.min(100,a.work/j.target*100);$('water-label').textContent=`Water ${Math.round(a.water)}%`;$('water-meter').value=a.water;$('water').style.height=waterHeight(a.water)+'%';$('ability').textContent=a.charge>=abilityCost(p)?'Emergency pump ↓25%':`Pump charging ${a.charge}/${abilityCost(p)}`;$('ability').disabled=paused||busy||a.charge<abilityCost(p);}
function board(){if(!p.active)return;$('board').innerHTML=p.active.board.map((t,i)=>`<button class="tile t${t}${selected===i?' selected':''}" data-cell="${i}" aria-label="Row ${Math.floor(i/W)+1}, column ${i%W+1}: ${pieceNames[t]}" aria-pressed="${selected===i}">${pieceSVG(t)}</button>`).join('');meters();}
function fullscreen(){try{document.documentElement.requestFullscreen?.().catch(()=>{});}catch{}}
function enter(){if(!p.active)return;paused=false;lastTick=performance.now();selected=null;$('play').hidden=false;document.body.classList.add('playing');const j=JOBS.find(j=>j.id===p.active.job);$('job-name').textContent=j.name;$('job-objective').textContent=`Complete ${j.target} work before the hold floods`;say('Swap sideways to match 3 patterns.');board();fullscreen();}
function start(id){const j=JOBS.find(j=>j.id===id);if(!j||p.active||rank(p)<j.rank)return;const level=difficulty(p,j);p.active={job:id,status:'running',level,board:fresh(level),water:45,work:0,swaps:0,time:0,charge:abilityCost(p)};save();enter();}
function leave(){paused=true;$('play').hidden=true;document.body.classList.remove('playing');for(const d of document.querySelectorAll('dialog[open]'))d.close();try{document.exitFullscreen?.().catch(()=>{});}catch{}save();harbor();}
function pause(){if(!p.active||$('play').hidden)return;paused=true;meters();save();if(!$('pause-dialog').open)$('pause-dialog').showModal();}
function finish(success){const result=reward(p,success);if(!result)return;paused=true;save();for(const d of document.querySelectorAll('dialog[open]'))d.close();$('result-kicker').textContent=success?'JOB COMPLETED':'HOLD FLOODED';$('result-title').textContent=success?'Back on the water.':'The harbor can wait.';$('result-copy').textContent=`${result.job} · ${Math.floor(result.work)} work in ${result.swaps} swaps. ${success?'Your work paid for new equipment and brought you closer to the next rank.':'Try a different crew specialty, use the emergency pump, or return with stronger equipment.'}`;$('result-rewards').textContent=success?`+${result.coins} coins · +${result.xp} XP`:'No rewards earned. Your equipment and coins are safe.';$('result-dialog').showModal();}
function check(){if(!p.active||busy)return;const a=p.active,j=JOBS.find(j=>j.id===a.job);if(a.work>=j.target)finish(true);else if(a.water>=100)finish(false);}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function clear(cells,work,label){const a=p.active;a.work+=work;a.water=Math.max(0,a.water-work*.6*pumpFactor(p));say(`${label} · +${work.toFixed(1)} work`);cells.forEach(i=>$('board').children[i]?.classList.add('cleared'));meters();await wait(160);a.board=refill(a.board,cells,a.level);board();}
async function swap(i,j){const a=p.active;if(!a||paused||busy||!Number.isInteger(i)||!Number.isInteger(j)||i<0||j<0||i>=72||j>=72||Math.floor(i/W)!==Math.floor(j/W)||Math.abs(i-j)!==1)return false;const special=specialClear(a.board,i,j);if(special.blocked){say('Crabs cannot swap. Drain the water to release them.');return false;}if(a.board[i]===a.board[j])return false;busy=true;selected=null;a.swaps++;
try{if(special.cells.length)await clear(special.cells,special.cells.filter(i=>a.board[i]!==7).length*.5,special.kind==='puffer'?'Pufferfish burst':'Jellyfish pattern sweep');else{[a.board[i],a.board[j]]=[a.board[j],a.board[i]];board();}let cascade=!!special.cells.length,changed=!!special.cells.length;for(let n=0;n<100;n++){const g=groups(a.board);if(g.length){let work=matchScore(g,cascade)/10;if(p.character==='alex'&&g.length>1)work*=1.25;await clear([...new Set(g.flat())],work,g.length>1?`${g.length}-line combo`:cascade?'Cascade':'Pumps working');cascade=true;changed=true;continue;}const crabs=releasedCrabs(a.board,a.water);if(crabs.length){await clear(crabs,8*crabs.length**2,'Crabs released');cascade=true;changed=true;continue;}break;}if(changed)a.charge=Math.min(abilityCost(p),a.charge+1);else say('Positioned. Set up your next match.');}finally{busy=false;meters();save();check();}return true;}
$('crew').addEventListener('click',e=>{const b=e.target.closest('[data-crew]');if(b&&!p.active){p.character=b.dataset.crew;save();harbor();}});
$('jobs').addEventListener('click',e=>{const b=e.target.closest('[data-job]');if(b)start(b.dataset.job);});
$('upgrades').addEventListener('click',e=>{const b=e.target.closest('[data-upgrade]');if(b&&buy(p,b.dataset.upgrade)){save();harbor();$('notice').textContent='Equipment improved. Your next job will use the upgrade.';}});
$('board').addEventListener('click',e=>{const b=e.target.closest('[data-cell]');if(!b||paused||busy)return;const i=Number(b.dataset.cell);if(selected!==null&&Math.floor(selected/W)===Math.floor(i/W)&&Math.abs(selected-i)===1)void swap(selected,i);else{selected=selected===i?null:i;board();}});
let down=null;$('board').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-cell]');if(b)down={i:Number(b.dataset.cell),x:e.clientX,y:e.clientY};});$('board').addEventListener('pointerup',e=>{if(!down)return;const d=down;down=null;if(Math.abs(e.clientX-d.x)>18&&Math.abs(e.clientX-d.x)>Math.abs(e.clientY-d.y)){void swap(d.i,d.i+Math.sign(e.clientX-d.x));}});$('board').addEventListener('pointercancel',()=>down=null);
$('ability').onclick=()=>{const a=p.active;if(!a||paused||busy||a.charge<abilityCost(p))return;a.water=Math.max(0,a.water-25);a.charge=0;say('Emergency pump · water lowered by 25%');meters();save();};
$('pause').onclick=pause;$('continue').onclick=()=>{$('pause-dialog').close();paused=false;lastTick=performance.now();meters();};$('back-harbor').onclick=()=>{if(busy){say('Finishing this clear. Try again in a moment.');return;}leave();};$('resume').onclick=enter;$('fullscreen').onclick=fullscreen;$('end-job').onclick=()=>{if(!busy)$('abandon-dialog').showModal();};$('cancel-abandon').onclick=()=>$('abandon-dialog').close();$('confirm-abandon').onclick=()=>{if(busy)return;p.active=null;leave();};$('result-close').onclick=leave;$('help').onclick=()=>$('help-dialog').showModal();$('help-close').onclick=()=>$('help-dialog').close();
for(const id of ['pause-dialog','result-dialog','abandon-dialog'])$(id).addEventListener('cancel',e=>e.preventDefault());
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('pagehide',save);
setInterval(()=>{const now=performance.now(),dt=Math.min(1,(now-lastTick)/1000);lastTick=now;if(paused||!p.active)return;const a=p.active,j=JOBS.find(j=>j.id===a.job);a.time+=dt;a.water=Math.min(100,a.water+j.leak*leakFactor(p)*dt);meters();check();saveClock+=dt;if(saveClock>=5&&!busy){save();saveClock=0;}},250);
if(navigator.modelContext){navigator.modelContext.registerTool({name:'read_puzzle',description:'Read current harbor job, board and crew progression.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({profile:p,paused})}]})});navigator.modelContext.registerTool({name:'swap_tiles',description:'Swap horizontally adjacent puzzle cells, indexed 0 through 71.',inputSchema:{type:'object',properties:{from:{type:'integer'},to:{type:'integer'}},required:['from','to']},execute:async({from,to})=>({content:[{type:'text',text:JSON.stringify({swapped:await swap(from,to)})}]})});}
harbor();
